module AccumulatorINT8INT4Inner(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [13:0] io_in_bits_sumIn,
  input  [31:0] io_in_bits_inC,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_result,
  output [4:0]  io_out_bits_fflags
);

  wire        s1_ready;
  reg         s0Pipe_rValid;
  reg  [31:0] s0Pipe_rBits_aAcc;
  reg  [31:0] s0Pipe_rBits_bAcc;
  wire        s0_ready = ~s0Pipe_rValid | s1_ready;
  reg         io_out_rValid;
  reg  [31:0] io_out_rBits_result;
  reg  [4:0]  io_out_rBits_fflags;
  assign s1_ready = ~io_out_rValid | io_out_ready;
  always @(posedge clock) begin
    automatic logic _s0Pipe_T;
    automatic logic _io_out_T;
    _s0Pipe_T = s0_ready & io_in_valid;
    _io_out_T = s1_ready & s0Pipe_rValid;
    if (reset) begin
      s0Pipe_rValid <= 1'h0;
      io_out_rValid <= 1'h0;
    end
    else begin
      s0Pipe_rValid <= _s0Pipe_T | ~(s1_ready & s0Pipe_rValid) & s0Pipe_rValid;
      io_out_rValid <= _io_out_T | ~(io_out_ready & io_out_rValid) & io_out_rValid;
    end
    if (_s0Pipe_T) begin
      s0Pipe_rBits_aAcc <= {{18{io_in_bits_sumIn[13]}}, io_in_bits_sumIn};
      s0Pipe_rBits_bAcc <= io_in_bits_inC;
    end
    if (_io_out_T) begin
      automatic logic [31:0] addAcc = s0Pipe_rBits_aAcc + s0Pipe_rBits_bAcc;
      io_out_rBits_result <= addAcc;
      io_out_rBits_fflags <=
        {4'h0,
         s0Pipe_rBits_aAcc[31] == s0Pipe_rBits_bAcc[31]
           & addAcc[31] != s0Pipe_rBits_aAcc[31]};
    end
  end // always @(posedge)
  assign io_in_ready = s0_ready;
  assign io_out_valid = io_out_rValid;
  assign io_out_bits_result = io_out_rBits_result;
  assign io_out_bits_fflags = io_out_rBits_fflags;
